"use client";

import { useState } from "react";
import { userApi } from "@/services/api";
import { Button, EmptyState, ErrorState, formatDate, Icon, PageHeader, Panel, Skeleton, StatePill, toast, useAccessToken, useVendorQuery } from "@/components/portal";

type Ticket={id:string;vendor_name:string|null;booking_id:string|null;category:string;subject:string;status:string;priority:string;created_at:string;updated_at:string;message_count?:number;messages?:Array<{id:string;sender_role:string;body:string;is_internal:boolean;created_at:string}>};
type TicketPage={items:Ticket[];total:number};
export default function VendorSupportPage(){const token=useAccessToken();const q=useVendorQuery<TicketPage>("/support",token);const[selected,setSelected]=useState<string|null>(null);const detail=useVendorQuery<Ticket>(selected?`/support/${selected}`:"",token);const[category,setCategory]=useState("business");const[subject,setSubject]=useState("");const[message,setMessage]=useState("");const[bookingId,setBookingId]=useState("");const[reply,setReply]=useState("");const[busy,setBusy]=useState(false);
  async function create(event:React.FormEvent){event.preventDefault();if(!token)return;setBusy(true);try{await userApi("/support/vendor",token,{method:"POST",headers:{"Idempotency-Key":crypto.randomUUID()},body:JSON.stringify({category,subject,message,...(bookingId.trim()?{booking_id:bookingId.trim()}: {})})});setSubject("");setMessage("");setBookingId("");q.reload();toast("Support request saved");}catch(error){toast(error instanceof Error?error.message:"Request was not saved");}finally{setBusy(false);}}
  async function respond(event:React.FormEvent){event.preventDefault();if(!token||!selected||!reply.trim())return;setBusy(true);try{await userApi(`/support/${selected}/messages`,token,{method:"POST",headers:{"Idempotency-Key":crypto.randomUUID()},body:JSON.stringify({message:reply.trim()})});setReply("");detail.reload();q.reload();toast("Reply saved");}catch(error){toast(error instanceof Error?error.message:"Reply was not saved");}finally{setBusy(false);}}
  return <><PageHeader eyebrow="VENDOR CARE" title="Support tickets" description="Create a business support request and continue the persisted conversation with VoltStop support."/><div className="dashboard-column"><Panel className="panel-pad"><h2>Open a request</h2><form onSubmit={create}><div className="form-grid"><label className="label-control">Category<select className="select-control" value={category} onChange={(e)=>setCategory(e.target.value)}>{["business","booking","payment","technical","account","other"].map((v)=><option key={v}>{v}</option>)}</select></label><label className="label-control">Subject<input className="input-control" minLength={4} maxLength={160} required value={subject} onChange={(e)=>setSubject(e.target.value)}/></label><label className="label-control">Related booking ID (optional)<input className="input-control" value={bookingId} onChange={(e)=>setBookingId(e.target.value)}/></label></div><label className="label-control">Message<textarea className="textarea-control" minLength={8} maxLength={4000} required value={message} onChange={(e)=>setMessage(e.target.value)}/></label><Button disabled={busy||!token}>{busy?"Saving…":"Submit support request"}</Button></form></Panel><Panel className="panel-pad"><h2>Your tickets</h2>{q.loading?<Skeleton rows={5}/>:q.error?<ErrorState message={q.error} onRetry={q.reload}/>:!q.data?.items.length?<EmptyState title="No support tickets" description="Requests you submit will appear here."/>:<div className="data-table-wrap"><table className="data-table"><thead><tr><th>Subject</th><th>Category</th><th>Booking</th><th>Status</th><th>Priority</th><th>Updated</th><th>Action</th></tr></thead><tbody>{q.data.items.map((ticket)=><tr key={ticket.id}><td>{ticket.subject}</td><td>{ticket.category}</td><td>{ticket.booking_id?.slice(0,12)??"—"}</td><td><StatePill value={ticket.status}/></td><td><StatePill value={ticket.priority}/></td><td>{formatDate(ticket.updated_at,{dateStyle:"medium",timeStyle:"short"})}</td><td><button className="action-link" onClick={()=>setSelected(ticket.id)}>Open conversation</button></td></tr>)}</tbody></table></div>}</Panel></div>
  {selected&&<div className="modal-backdrop" onMouseDown={(e)=>e.target===e.currentTarget&&setSelected(null)}><section className="modal-card" role="dialog" aria-modal="true"><div className="modal-head"><div><h2>{detail.data?.subject??"Support conversation"}</h2><p>Messages are saved only after the API confirms.</p></div><button className="close-button" aria-label="Close" onClick={()=>setSelected(null)}><Icon name="close"/></button></div>{detail.loading?<Skeleton rows={5}/>:detail.error?<ErrorState message={detail.error} onRetry={detail.reload}/>:<><div className="support-thread">{(detail.data?.messages??[]).filter((item)=>!item.is_internal).map((item)=><article className="support-message" key={item.id}><div><strong>{item.sender_role}</strong><time>{formatDate(item.created_at,{dateStyle:"medium",timeStyle:"short"})}</time></div><p>{item.body}</p></article>)}</div>{!['resolved','closed'].includes(detail.data?.status??"")&&<form onSubmit={respond}><label className="label-control">Reply<textarea className="textarea-control" minLength={2} maxLength={4000} required value={reply} onChange={(e)=>setReply(e.target.value)}/></label><Button disabled={busy}>{busy?"Saving…":"Send reply"}</Button></form>}</>}</section></div>}</>;
}
